import{_ as e,o as a,c as r,ae as t}from"./chunks/framework.Dn7Y7LSn.js";const h=JSON.parse('{"title":"Module 8: Introduction to Laravel","description":"","frontmatter":{},"headers":[],"relativePath":"module-8/laravel-intro.md","filePath":"module-8/laravel-intro.md"}'),n={name:"module-8/laravel-intro.md"};function l(i,o,s,p,d,c){return a(),r("div",null,[...o[0]||(o[0]=[t('<h1 id="module-8-introduction-to-laravel" tabindex="-1">Module 8: Introduction to Laravel <a class="header-anchor" href="#module-8-introduction-to-laravel" aria-label="Permalink to &quot;Module 8: Introduction to Laravel&quot;">​</a></h1><p>পিএইচপির অনেকগুলো জনপ্রিয় ফ্রেমওয়ার্ক রয়েছে, যেমন: CodeIgniter, Symfony, CakePHP, Yii ইত্যাদি। তবে বর্তমানে সবচেয়ে জনপ্রিয় ফ্রেমওয়ার্ক হলো <strong>Laravel</strong>।</p><h2 id="কেন-লারাভেল-এত-জনপ্রিয়-why-laravel-is-so-popular" tabindex="-1">কেন লারাভেল এত জনপ্রিয়? (Why Laravel is so popular?) <a class="header-anchor" href="#কেন-লারাভেল-এত-জনপ্রিয়-why-laravel-is-so-popular" aria-label="Permalink to &quot;কেন লারাভেল এত জনপ্রিয়? (Why Laravel is so popular?)&quot;">​</a></h2><p>১. <strong>Feature Rich:</strong> এতে প্রচুর বিল্ট-ইন ফিচার রয়েছে যা ডেভেলপমেন্টকে অনেক সহজ করে দেয়। ২. <strong>Developer Experience:</strong> লারাভেলের কোড সিনট্যাক্স অনেক সুন্দর এবং রিডাবল। ৩. <strong>Rich Ecosystem:</strong> লারাভেলের রয়েছে বিশাল ইকোসিস্টেম। যেমন: Breeze, Cashier, Vapor, Forge ইত্যাদি। ৪. <strong>Vibrant Community:</strong> এর কমিউনিটি অত্যন্ত শক্তিশালী, ফলে যেকোনো সমস্যায় সমাধান পাওয়া সহজ। ৫. <strong>Fast Development:</strong> লারাভেল দিয়ে খুব দ্রুত MVP (Minimum Viable Product) বানিয়ে ফেলা যায়।</p><hr><h2 id="লারাভেলের-মূল-কম্পোনেন্টসমূহ-web-application-components" tabindex="-1">লারাভেলের মূল কম্পোনেন্টসমূহ (Web Application Components) <a class="header-anchor" href="#লারাভেলের-মূল-কম্পোনেন্টসমূহ-web-application-components" aria-label="Permalink to &quot;লারাভেলের মূল কম্পোনেন্টসমূহ (Web Application Components)&quot;">​</a></h2><p>একটি পূর্ণাঙ্গ ফ্রেমওয়ার্ক হিসেবে লারাভেলে নিচের বিষয়গুলো হ্যান্ডেল করার মেকানিজম থাকে:</p><ul><li><strong>URL Routing:</strong> কোন ইউআরএলে রিকোয়েস্ট আসলে কি হবে তা ঠিক করা।</li><li><strong>HTTP Request/Response Handling:</strong> ক্লায়েন্টের কাছ থেকে ডেটা নেওয়া এবং রেসপন্স পাঠানো।</li><li><strong>ORM (Eloquent):</strong> অবজেক্ট ওরিয়েন্টেড পদ্ধতিতে ডাটাবেজের সাথে কমিউনিকেশন।</li><li><strong>Template Engine (Blade):</strong> সহজে এইচটিএমএল এবং পিএইচপি কোড লেখা।</li><li><strong>Session Management:</strong> ইউজারের সেশন হ্যান্ডেল করা।</li><li><strong>Authentication &amp; Authorization:</strong> লগইন এবং পারমিশন ম্যানেজমেন্ট।</li><li><strong>Error Handling &amp; Testing:</strong> কোড টেস্ট করা এবং এরর ডিবাগ করা।</li></ul><hr><h2 id="লারাভেল-এবং-সিম্ফনি-laravel-vs-symfony" tabindex="-1">লারাভেল এবং সিম্ফনি (Laravel vs Symfony) <a class="header-anchor" href="#লারাভেল-এবং-সিম্ফনি-laravel-vs-symfony" aria-label="Permalink to &quot;লারাভেল এবং সিম্ফনি (Laravel vs Symfony)&quot;">​</a></h2><p>লারাভেল পুরোপুরি সিম্ফনি দিয়ে বানানো নয়, তবে লারাভেল ইন্টারনালি অনেকগুলো <strong>Symfony Components</strong> ব্যবহার করে। যেমন: Routing, Console, HTTP Foundation ইত্যাদি। লারাভেল কখনো সরাসরি এই কম্পোনেন্টগুলো ব্যবহার করে, আবার কখনো এর ওপর নিজের মতো র‍্যাপার (Wrapper) বানিয়ে নেয়।</p><hr><h2 id="প্রজেক্ট-স্ট্রাকচার-এবং-গুরুত্বপূর্ণ-ডিরেক্টরি" tabindex="-1">প্রজেক্ট স্ট্রাকচার এবং গুরুত্বপূর্ণ ডিরেক্টরি <a class="header-anchor" href="#প্রজেক্ট-স্ট্রাকচার-এবং-গুরুত্বপূর্ণ-ডিরেক্টরি" aria-label="Permalink to &quot;প্রজেক্ট স্ট্রাকচার এবং গুরুত্বপূর্ণ ডিরেক্টরি&quot;">​</a></h2><ul><li><strong>app:</strong> এখানে অ্যাপ্লিকেশনের মূল লজিক (Models, Controllers, Services) থাকে।</li><li><strong>config:</strong> সব কনফিগারেশন ফাইল এখানে থাকে। হার্ড-কোডেড ভ্যালু না রেখে এখানে রাখা ভালো।</li><li><strong>database:</strong> মাইগ্রেশন, সিডার এবং ফ্যাক্টরি ফাইল এখানে থাকে।</li><li><strong>public:</strong> ইন্ডেক্স ফাইল (<code>index.php</code>), ইমেজ, সিএসএস এবং জেএস ফাইল এখানে থাকে। এটি পাবলিকলি অ্যাক্সেসিবল।</li><li><strong>resources:</strong> ব্লেড ফাইল (Views) এবং কম্পাইল না করা অ্যাসেটগুলো এখানে থাকে।</li><li><strong>routes:</strong> সব রাউট ডেফিনিশন (web.php, api.php) এখানে থাকে।</li><li><strong>storage:</strong> লগ ফাইল এবং ইউজার আপলোডকৃত সেনসিটিভ ফাইল এখানে থাকে।</li><li><strong>vendor:</strong> কম্পোজার দিয়ে ইন্সটল করা সব থার্ড পার্টি প্যাকেজ এখানে থাকে।</li></ul><hr><h2 id="লারাভেল-১১-এর-উল্লেখযোগ্য-পরিবর্তনসমূহ" tabindex="-1">লারাভেল ১১-এর উল্লেখযোগ্য পরিবর্তনসমূহ <a class="header-anchor" href="#লারাভেল-১১-এর-উল্লেখযোগ্য-পরিবর্তনসমূহ" aria-label="Permalink to &quot;লারাভেল ১১-এর উল্লেখযোগ্য পরিবর্তনসমূহ&quot;">​</a></h2><p>লারাভেল ১১-এ ডিরেক্টরি স্ট্রাকচার অনেক বেশি ক্লিন এবং মিনিমাল করা হয়েছে। আগের ভার্সনগুলোর অনেক ফাইল এখন ইন্টারনালি হ্যান্ডেল করা হয়:</p><ul><li><strong>Middleware &amp; Exceptions:</strong> আগে <code>app/Http/Middleware</code> এবং <code>app/Exceptions/Handler.php</code> ফাইলে এগুলো হ্যান্ডেল করা হতো। এখন এগুলো সরাসরি <code>bootstrap/app.php</code> ফাইল থেকে কনফিগার করা হয়।</li><li><strong>Kernel.php:</strong> <code>app/Http/Kernel.php</code> এবং <code>app/Console/Kernel.php</code> ফাইল দুটি সরিয়ে নেওয়া হয়েছে। এখন রাউটিং, মিডলওয়্যার এবং এক্সেপশন হ্যান্ডেলিংয়ের সব কাজ <code>bootstrap/app.php</code> তে <code>Application::configure()</code> মেথডের মাধ্যমে করা হয়।</li><li><strong>Config Files:</strong> লারাভেল ১১-এ সব কনফিগ ফাইল ডিফল্টভাবে থাকে না। প্রয়োজন হলে <code>php artisan config:publish</code> কমান্ড দিয়ে সেগুলো নিয়ে আসা যায়।</li></ul><hr><h2 id="এনভায়রনমেন্ট-ভেরিয়েবল-env" tabindex="-1">এনভায়রনমেন্ট ভেরিয়েবল (.env) <a class="header-anchor" href="#এনভায়রনমেন্ট-ভেরিয়েবল-env" aria-label="Permalink to &quot;এনভায়রনমেন্ট ভেরিয়েবল (.env)&quot;">​</a></h2><p>যে ভ্যালুগুলো পরিবেশভেদে (Staging, Production) পরিবর্তন হয়, সেগুলো আমরা <code>.env</code> ফাইলে রাখি। যেমন: ডাটাবেজ ক্রেডেনশিয়াল, এপিআই কি ইত্যাদি। কোডের ভেতর সরাসরি <code>.env</code> এর কি ব্যবহার না করে <code>config</code> ফাইলের মাধ্যমে ব্যবহার করা বেস্ট প্র্যাকটিস।</p>',21)])])}const u=e(n,[["render",l]]);export{h as __pageData,u as default};
